contract InvMutTest {
    C c;
    address deployer;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We attempt to call OpenToThePublic from this contract (not the original owner).
    // The test is parameterized by an arbitrary uint and an arbitrary amount to allow sending value
    // to other calls if desired; here we won't send Ether to OpenToThePublic.
    function run(uint256 dummy, uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        // Read observable before-state: currentBetLimit and eth balance
        uint256 beforeBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        // Try calling OpenToThePublic and capture whether it reverted.
        bool reverted;
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call, bet limit must be unchanged if the call succeeded (owner should be only allowed to change other values, but OpenToThePublic only toggles openToPublic)
        uint256 afterBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        // General rule: If the call did not revert then bet limit is preserved and contract balance unchanged;
        // If it reverted then nothing else is required. This asserts for all inputs.
        assert(reverted || (afterBetLimit == beforeBetLimit && afterBalance == beforeBalance));
    }

    // Allow receiving Ether if needed
    receive() external payable {}
}

