// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;
    address deployer;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 dummy, uint256 sendAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeBetLimit = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.OpenToThePublic() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { afterBetLimit = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue(reverted || (afterBetLimit == beforeBetLimit && afterBalance == beforeBalance));
    }

    function testFuzz_run(uint256 dummy, uint256 sendAmount) public {
        _run(dummy, sendAmount);
    }

    receive() external payable {}
}
